import { readFile, writeFile, rename } from "node:fs/promises";
import { existsSync } from "node:fs";
const root = new URL("../packages/tokens/", import.meta.url);
const data = JSON.parse(await readFile(new URL("tokens.json", root), "utf8"));
function rule(selector, values, extra = "") {
  return `${selector} {\n${Object.entries(values)
    .map(([key, value]) => `  --ui-${key}:${value};`)
    .join("\n")}\n${extra}}\n`;
}
let css =
  "/* Generated by scripts/build-tokens.mjs from tokens.json. Do not edit. */\n";
css += rule(
  ".ui-theme",
  data.base,
  "  --ui-font-scale:1; color-scheme:light; color:var(--ui-text); font-family:var(--ui-font-sans); font-size:calc(var(--ui-font-base)*var(--ui-font-scale)); line-height:1.6; font-variant-numeric:tabular-nums; -webkit-font-smoothing:antialiased;\n",
);
css += rule(
  ".ui-theme[data-ui-mode='dark']",
  data.dark,
  "  color-scheme:dark;\n",
);
for (const [skin, values] of Object.entries(data.skins)) {
  if (Object.keys(values.base).length)
    css += rule(`.ui-theme[data-ui-skin='${skin}']`, values.base);
  if (Object.keys(values.dark).length)
    css += rule(
      `.ui-theme[data-ui-skin='${skin}'][data-ui-mode='dark']`,
      values.dark,
    );
}
css += rule(".ui-theme[data-ui-density='compact']", data.compact);
for (const [palette, values] of Object.entries(data.palettes)) {
  if (Object.keys(values.base).length)
    css += rule(`.ui-theme[data-ui-palette='${palette}']`, values.base);
  if (Object.keys(values.dark).length)
    css += rule(
      `.ui-theme[data-ui-palette='${palette}'][data-ui-mode='dark']`,
      values.dark,
    );
}
for (const mode of ["light", "dark"]) {
  const values = Object.fromEntries(
    Object.entries(data.categories).flatMap(([name, modes]) =>
      Object.entries(modes[mode]).map(([role, value]) => [
        `category-${name}-${role}`,
        value,
      ]),
    ),
  );
  css += rule(
    mode === "light" ? ".ui-theme" : ".ui-theme[data-ui-mode='dark']",
    values,
  );
}
for (const name of Object.keys(data.categories)) {
  css += rule(
    `[data-ui-color='${name}']`,
    Object.fromEntries(
      ["soft", "ink", "solid"].map((role) => [
        `category-${role}`,
        `var(--ui-category-${name}-${role})`,
      ]),
    ),
  );
}
for (const [design, values] of Object.entries(data.designs))
  css += rule(`.ui-theme[data-ui-design='${design}']`, values);
for (const [font, values] of Object.entries(data.fonts)) {
  css += rule(`.ui-theme[data-ui-font='${font}']`, {
    "font-sans": values.family,
  });
  css += rule(`.ui-theme[data-ui-heading-font='${font}']`, {
    "font-heading": values.family,
  });
}
for (const [motion, values] of Object.entries(data.motions))
  css += rule(`.ui-theme[data-ui-motion='${motion}']`, values);
css +=
  "@media(pointer:coarse) { .ui-theme { --ui-control:44px; } }\n@media(prefers-reduced-motion:reduce) { .ui-theme { --ui-fast:0ms; --ui-normal:0ms; --ui-enter:0ms; } }\n";
const definitions = `// Generated from tokens.json. Do not edit.\nexport const definitions = ${JSON.stringify(data, null, 2)};\n`;
for (const [name, content] of [
  ["tokens.css", css],
  ["definitions.js", definitions],
]) {
  if (process.argv.includes("--check")) {
    if ((await readFile(new URL(name, root), "utf8")) !== content)
      throw new Error(`${name} is stale; run npm run build:tokens`);
  } else if (
    !existsSync(new URL(name, root)) ||
    (await readFile(new URL(name, root), "utf8")) !== content
  ) {
    const temporary = new URL(name + ".tmp", root);
    await writeFile(temporary, content, "utf8");
    await rename(temporary, new URL(name, root));
  }
}
console.log("Token outputs agree with the canonical JSON.");
